{
  "items": [
    {
      "name": "MvPolynomial.aeval_natDegree_le",
      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {σ : Type v} {R : Type u_2} [inst : CommSemiring R] {m n : ℕ} (F : MvPolynomial σ R),\n  F.totalDegree ≤ m →\n    ∀ (f : σ → Polynomial R), (∀ (i : σ), (f i).natDegree ≤ n) → ((MvPolynomial.aeval f) F).natDegree ≤ m * n"
    },
    {
      "name": "Polynomial.abs_isBoundedUnder_iff",
      "module_name": "Mathlib.Analysis.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} [inst : NormedField 𝕜] [inst_1 : LinearOrder 𝕜] [IsStrictOrderedRing 𝕜] (P : Polynomial 𝕜)\n  [OrderTopology 𝕜],\n  (Filter.IsBoundedUnder (fun x1 x2 => x1 ≤ x2) Filter.atTop fun x => |Polynomial.eval x P|) ↔ P.degree ≤ 0"
    },
    {
      "name": "Polynomial.tendsto_abv_aeval_atTop",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_2} {k : Type u_3} {α : Type u_4} [inst : CommSemiring R] [inst_1 : Ring A]\n  [inst_2 : Algebra R A] [inst_3 : Field k] [inst_4 : LinearOrder k] [IsStrictOrderedRing k] (abv : A → k)\n  [IsAbsoluteValue abv] (p : Polynomial R),\n  0 < p.degree →\n    (algebraMap R A) p.leadingCoeff ≠ 0 →\n      ∀ {l : Filter α} {z : α → A},\n        Filter.Tendsto (abv ∘ z) l Filter.atTop →\n          Filter.Tendsto (fun x => abv ((Polynomial.aeval (z x)) p)) l Filter.atTop"
    },
    {
      "name": "MvPolynomial.eval₂",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] → [inst_1 : CommSemiring S₁] → (R →+* S₁) → (σ → S₁) → MvPolynomial σ R → S₁"
    },
    {
      "name": "Polynomial.le_gaussNorm",
      "module_name": "Mathlib.RingTheory.Polynomial.GaussNorm",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {F : Type u_2} [inst : Semiring R] [inst_1 : FunLike F R ℝ] (v : F) {c : ℝ} (p : Polynomial R)\n  [ZeroHomClass F R ℝ] [NonnegHomClass F R ℝ], 0 ≤ c → ∀ (i : ℕ), v (p.coeff i) * c ^ i ≤ Polynomial.gaussNorm v c p"
    }
  ]
}

