      "type": " {R : Type u_1} [CommRing R] {σ : Type u_2} [Finite σ] [IsDomain R] (S : σ → Finset R) (Sne : ∀ (i : σ), (S i).Nonempty) (f : MvPolynomial σ R) (Heval : ∀ (x : σ → R), (∀ (i : σ), x i ∈ S i) → (MvPolynomial.eval x) f = 0) : ∃ h, (∀ (i : σ), ((∏ s ∈ S i, (MvPolynomial.X i - MvPolynomial.C s)) * h i).totalDegree ≤ f.totalDegree) ∧ f = (Finsupp.linearCombination (MvPolynomial σ R) fun i => ∏ r ∈ S i, (MvPolynomial.X i - MvPolynomial.C r)) h",
