      "type": " {ι : Type u_1} {κ : Type u_2} {R : Type u_3} [DecidableEq κ] [CommRing R] [DecidableEq R] (monoms : ι → Finset (κ →₀ ℕ)) (f : (i : ι) × ↥(monoms i) ⊕ κ → R) (i : ι) : (FreeCommRing.lift f) (FirstOrder.Ring.genericPolyMap monoms i) = (MvPolynomial.eval (f ∘ Sum.inr)) (↑((FirstOrder.Ring.mvPolynomialSupportLEEquiv monoms).symm (f ∘ Sum.inl)) i)",
      "module": "Mathlib.RingTheory.MvPolynomial.FreeCommRing"
    },
    {
      "name": "FirstOrder.realize_genericPolyMapSurjOnOfInjOn",
      "type": " {ι : Type u_1} {α : Type u_2} [Finite α] {K : Type u_3} [Field K] [FirstOrder.Ring.CompatibleRing K] [Finite ι] (φ : FirstOrder.Language.ring.Formula (α ⊕ ι)) (mons : ι → Finset (ι →₀ ℕ)) :\n  K ⊨ FirstOrder.genericPolyMapSurjOnOfInjOn φ mons ↔\n    ∀ (v : α → K) (p : { p // ∀ (i : ι), (p i).support ⊆ mons i }),\n      have f := fun v i => (MvPolynomial.eval v) (↑p i);\n      have S := {x | φ.Realize (Sum.elim v x)};\n      Set.MapsTo f S S → Set.InjOn f S → Set.SurjOn f S S",
      "module": "Mathlib.FieldTheory.AxGrothendieck"
    },
    {
      "name": "Height.logHeight_eval_le'",
