      "type": " {K : Type u_4} [Field K] {ι : Type u_5} {ι' : Type u_6} [Height.AdmissibleAbsValues K] [Finite ι'] [Finite ι] {N : ℕ} {p : ι' → MvPolynomial ι K} (hp : ∀ (i : ι'), (p i).IsHomogeneous N) (x : ι → K) : (Height.logHeight fun j => (MvPolynomial.eval x) (p j)) ≤ Real.log (max (Height.mulHeightBound p) 1) + ↑N * Height.logHeight x",
      "module": "Mathlib.NumberTheory.Height.MvPolynomial"
