      "name": "Height.mulHeight_eval_le",
      "type": " {K : Type u_4} [Field K] {ι : Type u_5} {ι' : Type u_6} [Height.AdmissibleAbsValues K] [Finite ι'] [Finite ι] {N : ℕ} {p : ι' → MvPolynomial ι K} (hp : ∀ (i : ι'), (p i).IsHomogeneous N) (x : ι → K) : (Height.mulHeight fun j => (MvPolynomial.eval x) (p j)) ≤ max (Height.mulHeightBound p) 1 * Height.mulHeight x ^ N",
      "module": "Mathlib.NumberTheory.Height.MvPolynomial"
