    {
      "name": "AbsoluteValue.eval_mvPolynomial_le",
      "type": " {K : Type u_4} [Field K] {ι : Type u_5} [Finite ι] (v : AbsoluteValue K ℝ) {p : MvPolynomial ι K} {N : ℕ} (hp : p.IsHomogeneous N) (x : ι → K) : v ((MvPolynomial.eval x) p) ≤ (p.coeff.sum fun x c => v c) * (⨆ i, v (x i)) ^ N",
      "module": "Mathlib.NumberTheory.Height.MvPolynomial"
    },
    {
      "name": "Height.logHeight_eval_ge'",
      "type": " {K : Type u_6} [Field K] {ι : Type u_7} {ι' : Type u_8} [Fintype ι'] [Height.AdmissibleAbsValues K] [Finite ι] {M N : ℕ} {q : ι × ι' → MvPolynomial ι K} (hq : ∀ (a : ι × ι'), (q a).IsHomogeneous M) : ∃ C, ∀ (p : ι' → MvPolynomial ι K) {x : ι → K}, (∀ (k : ι), ∑ j, (MvPolynomial.eval x) (q (k, j)) * (MvPolynomial.eval x) (p j) = x k ^ (M + N)) → C + ↑N * Height.logHeight x ≤ Height.logHeight fun j => (MvPolynomial.eval x) (p j)",
      "module": "Mathlib.NumberTheory.Height.MvPolynomial"
    }
  ]
}

